-- Squashed from 5 prior migrations (see git log) on 2026-05-04.
-- App: mind-mapping. Generated by scripts/phase4-squash-app.mjs from a
-- pg_dump --schema-only of a freshly-migrated flagship_mind_mapping DB.
--
-- This is a hand-derived baseline migration: it captures the verified-
-- green schema produced by the prior multi-file migration set, in a
-- single replayable file. `mlcl create <app>` will scaffold this as
-- migration 0010 and the runtime migration runner will apply it as a
-- single transaction at first boot.
CREATE TABLE public.connections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    map_id uuid NOT NULL,
    source_node_id uuid NOT NULL,
    target_node_id uuid NOT NULL,
    label text,
    style jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


